import * as React from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { AuthProvider, PrivateRoute } from "./Auth";
import { GameProvider } from "./Contexts";
import Layout from "./Components/Layout";
import {
  Campaign,
  Characters,
  CharacterDisplay,
  CharacterForm,
  CharacterNotes,
  Compendium,
  Features,
  Dashboard,
  Home,
  JournalEntry,
  Login,
  MobileAttacks,
  MobileGear,
  MobileSpells,
  Settings,
  SignUp,
} from "./Pages";
import { ErrorProvider } from "./Errors";
import { ApolloProvider } from "@apollo/client";
import { useClient } from "./Graphql";
import GameSubRoute from "./Contexts/GameSubRoute";
import { Toaster } from "./Components/ui";
import "./Components/Shell/appearance";

const App = () => {
  const client = useClient();
  return (
    <div className="App">
      <ApolloProvider client={client}>
        <ErrorProvider>
          <AuthProvider>
            <GameProvider>
              <Layout>
                <Routes>
                  <Route path="/" element={<Home />} />
                  <Route path="/login" element={<Login />} />
                  <Route path="/sign-up" element={<SignUp />} />
                  <Route element={<PrivateRoute />}>
                    <Route path="/dashboard" element={<Dashboard />} />
                    <Route path="/settings" element={<Settings />} />
                    <Route path="/campaigns/:id" element={<Campaign />} />
                    <Route
                      path="/campaigns/:id/journal/:entryId"
                      element={<JournalEntry />}
                    />
                    <Route
                      path="/compendium"
                      element={<Navigate to="/compendium/spells" replace />}
                    />
                    <Route path="/compendium/:tab" element={<Compendium />} />
                    <Route
                      path="/spells"
                      element={<Navigate to="/compendium/spells" replace />}
                    />
                    <Route
                      path="/items"
                      element={<Navigate to="/compendium/items" replace />}
                    />
                    <Route element={<GameSubRoute />}>
                      <Route
                        path="characters/create"
                        element={<CharacterForm />}
                      />
                      <Route
                        path="characters/:id/edit"
                        element={<CharacterForm />}
                      />
                      <Route
                        path="characters/:id/features"
                        element={<Features />}
                      />
                      <Route
                        path="characters/:id/notes"
                        element={<CharacterNotes />}
                      />
                      <Route
                        path="characters/:id/attacks"
                        element={<MobileAttacks />}
                      />
                      <Route
                        path="characters/:id/spells"
                        element={<MobileSpells />}
                      />
                      <Route
                        path="characters/:id/gear"
                        element={<MobileGear />}
                      />
                      <Route
                        path="characters/:id"
                        element={<CharacterDisplay />}
                      />
                      <Route path="characters" element={<Characters />} />
                    </Route>
                  </Route>
                </Routes>
              </Layout>
            </GameProvider>
          </AuthProvider>
        </ErrorProvider>
      </ApolloProvider>
      <Toaster />
    </div>
  );
};

export default App;
